import React from 'react'
import { Link } from 'gatsby'
import Layout from '../components/layout'
import SEO from '../components/SEO'
import { /*Link,*/ graphql, useStaticQuery } from 'gatsby'
import unified from 'unified';
import markdown from 'remark-parse';
import html from 'remark-html';

const AboutPage = () => {


  const data = useStaticQuery(
    graphql`query  {
        allAirtable(filter: {table: {eq: "WorkExperience"}}) {
          nodes {
            data {
              CompanyName
              StartPosition
              EndPosition
              ExperienceSummary
              ProjectName
              Key_Achievements
              Location
              StartDateFmted:StartDate(formatString:"YYYYMMDD")
              StartDate(formatString: "MMM-YYYY")
              EndDate(formatString: "MMM-YYYY")
              CompanyLogo {
                height
                url
                width
                id
              }
              TechStack
            }
          }
        }
      }`
  )
  console.log(data);
  return (
    <div>
      <Layout>
        <SEO title="About Me - Aadism" description="Know more about me , my professional journey" />
        <h1>About Me</h1>
        <p><Link to="/contact">Want to work with me?</Link></p>
        <div>
          <h2>Work Experience</h2>
          <hr style={{ backgroundColor: "white" }} />
          {data.allAirtable.nodes
            .sort((a, b) => Number(b.data.StartDateFmted) - Number(a.data.StartDateFmted))
            .map((node) => {
              console.log(node);

              return (
                <div style={{ padding: "1em" }}>

                  <img src={`${node.data.CompanyLogo ? node.data.CompanyLogo[0].url : ""}`} height="50rem"></img>
                  <h3>{node.data.CompanyName}</h3>
                  <h3>{node.data.Location}</h3>
                  <h6>{`${node.data.StartDate} ➔ ${node.data.EndDate ? node.data.EndDate : "Current"}`}</h6>
                  <h6>{`${node.data.StartPosition} ${node.data.EndPosition && node.data.EndPosition !== node.data.StartPosition ? " ➔ " + node.data.EndPosition : ""}`}</h6>
                  <b>Roles and Responsibilities</b>
                  <div
                    dangerouslySetInnerHTML={{
                      __html: unified()
                        .use(markdown)
                        .use(html)
                        .processSync(node.data.ExperienceSummary)
                    }}
                  />
                  <b>Key Achievements</b>
                  <div
                    dangerouslySetInnerHTML={{
                      __html: unified()
                        .use(markdown)
                        .use(html)
                        .processSync(node.data.Key_Achievements)
                    }}
                  />
                  {
                    node.data.TechStack &&
                    <>
                      <b>Technologies Worked On</b>
                      <ul>
                        {node.data.TechStack.map((tech) => {
                          return (<li>{tech}</li>)
                        })}
                      </ul>
                    </>
                  }
                </div>
              )
            })}
        </div>
      </Layout>
    </div>
  )
}

export default AboutPage